package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="succession_development_review",uniqueConstraints=@UniqueConstraint(name="uk_succ_dev_review_sequence",columnNames={"agency_id","plan_id","review_sequence"}))
public class SuccessionDevelopmentReview extends RspAuditedEntity{
 public enum Recommendation{CONTINUE,COMPLETE,REMOVE_FROM_POOL}
 @Column(name="plan_id",nullable=false,length=36)private String planId;@Column(name="review_sequence",nullable=false)private int reviewSequence;@Column(name="review_date",nullable=false)private LocalDate reviewDate;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Recommendation recommendation;@Column(name="employee_visible_summary",nullable=false,length=4000)private String employeeVisibleSummary;@Column(name="restricted_rationale",nullable=false,length=4000)private String restrictedRationale;@Column(name="reviewed_by",nullable=false,length=100)private String reviewedBy;@Column(name="reviewed_at",nullable=false)private Instant reviewedAt;@Column(name="next_review_on")private LocalDate nextReviewOn;
 protected SuccessionDevelopmentReview(){}public SuccessionDevelopmentReview(String agency,String plan,int sequence,LocalDate date,Recommendation recommendation,String visible,String restricted,String actor,Instant at,LocalDate next){super(agency);planId=requiredText(plan,"planId");if(sequence<1)throw new IllegalArgumentException("reviewSequence must be positive");reviewSequence=sequence;reviewDate=java.util.Objects.requireNonNull(date);this.recommendation=java.util.Objects.requireNonNull(recommendation);employeeVisibleSummary=requiredText(visible,"employeeVisibleSummary");restrictedRationale=requiredText(restricted,"restrictedRationale");reviewedBy=requiredText(actor,"actor");reviewedAt=at;nextReviewOn=next;if(recommendation==Recommendation.CONTINUE&&(next==null||!next.isAfter(date)))throw new IllegalArgumentException("A continuing review requires a later next review date");}
 public String getPlanId(){return planId;}public int getReviewSequence(){return reviewSequence;}public LocalDate getReviewDate(){return reviewDate;}public Recommendation getRecommendation(){return recommendation;}public String getEmployeeVisibleSummary(){return employeeVisibleSummary;}public String getRestrictedRationale(){return restrictedRationale;}public String getReviewedBy(){return reviewedBy;}public Instant getReviewedAt(){return reviewedAt;}public LocalDate getNextReviewOn(){return nextReviewOn;}
}
